solution.Suit.java:
enum Suit {
    CLUBS('C'), DIAMONDS('D'), HEARTS('H'), SPADES('S');

    final char symbol;
    Suit(char symbol) { this.symbol = symbol; }

    static Suit of(char c) {
        for (Suit s : values()) if (s.symbol == c) return s;
        throw new IllegalArgumentException("unknown suit " + c);
    }
}

solution.Rank.java:
enum Rank {
    TWO('2'), THREE('3'), FOUR('4'), FIVE('5'), SIX('6'), SEVEN('7'), EIGHT('8'), NINE('9'),
    TEN('T'), JACK('J'), QUEEN('Q'), KING('K'), ACE('A');

    final char symbol;
    Rank(char symbol) { this.symbol = symbol; }

    static Rank of(char c) {
        for (Rank r : values()) if (r.symbol == c) return r;
        throw new IllegalArgumentException("unknown rank " + c);
    }
}

solution.Card.java:
record Card(Rank rank, Suit suit) {
    static Card parse(String text) {
        if (text == null || text.length() != 2) throw new IllegalArgumentException("not a card: " + text);
        return new Card(Rank.of(text.charAt(0)), Suit.of(text.charAt(1)));
    }

    @Override
    public String toString() { return "" + rank.symbol + suit.symbol; }
}

solution.Deck.java:
import java.util.*;

class Deck {
    private final List<Card> cards = new ArrayList<>();

    Deck() {
        for (Suit s : Suit.values())
            for (Rank r : Rank.values())
                cards.add(new Card(r, s));
    }

    int size() { return cards.size(); }

    Card deal() {
        if (cards.isEmpty()) throw new IllegalStateException("the deck is empty");
        return cards.remove(0);
    }

    void shuffle(Random random) { Collections.shuffle(cards, random); }
}

