import java.util.*;

record HandValue(Category category, List<Rank> tiebreak) implements Comparable<HandValue> {
    public int compareTo(HandValue other) {
        int c = category.compareTo(other.category);
        if (c != 0) return c;
        for (int i = 0; i < Math.min(tiebreak.size(), other.tiebreak.size()); i++) {
            c = tiebreak.get(i).compareTo(other.tiebreak.get(i));
            if (c != 0) return c;
        }
        return 0;
    }
}

solution.Poker.java:
import java.util.*;

class Poker {
    static List<Card> parseHand(String text) {
        List<Card> hand = new ArrayList<>();
        for (String part : text.trim().split("\\s+")) hand.add(Card.parse(part));
        return hand;
    }

    static HandValue evaluate(List<Card> five) {
        if (five.size() != 5) throw new IllegalArgumentException("a hand is 5 cards");
        for (int i = 0; i < 5; i++)
            for (int j = i + 1; j < 5; j++)
                if (five.get(i).equals(five.get(j))) throw new IllegalArgumentException("a hand is 5 different cards");
        Rank[] ranks = Rank.values();
        int[] counts = new int[ranks.length];
        for (Card c : five) counts[c.rank().ordinal()]++;

        // The distinct ranks, most frequent first, then higher first.
        List<Rank> byCount = new ArrayList<>();
        for (int n = 4; n >= 1; n--)
            for (int r = ranks.length - 1; r >= 0; r--)
                if (counts[r] == n) byCount.add(ranks[r]);

        boolean flush = true;
        for (Card c : five) if (c.suit() != five.get(0).suit()) flush = false;
        Rank straightHigh = null;
        if (byCount.size() == 5) {
            if (byCount.get(0).ordinal() - byCount.get(4).ordinal() == 4) straightHigh = byCount.get(0);
            else if (byCount.get(0) == Rank.ACE && byCount.get(1) == Rank.FIVE) straightHigh = Rank.FIVE;
        }

        int top = counts[byCount.get(0).ordinal()];
        int second = byCount.size() > 1 ? counts[byCount.get(1).ordinal()] : 0;
        Category category;
        if (straightHigh != null && flush) category = Category.STRAIGHT_FLUSH;
        else if (top == 4) category = Category.FOUR_OF_A_KIND;
        else if (top == 3 && second == 2) category = Category.FULL_HOUSE;
        else if (flush) category = Category.FLUSH;
        else if (straightHigh != null) category = Category.STRAIGHT;
        else if (top == 3) category = Category.THREE_OF_A_KIND;
        else if (top == 2 && second == 2) category = Category.TWO_PAIR;
        else if (top == 2) category = Category.PAIR;
        else category = Category.HIGH_CARD;

        List<Rank> tiebreak = straightHigh != null ? List.of(straightHigh) : List.copyOf(byCount);
        return new HandValue(category, tiebreak);
    }

    static int compare(String hand1, String hand2) {
        int c = evaluate(parseHand(hand1)).compareTo(evaluate(parseHand(hand2)));
        return c > 0 ? 1 : c < 0 ? -1 : 0;
    }
}

unitTests:
Function<String, Category> cat = hand -> Poker.evaluate(Poker.parseHand(hand)).category();

test("cards", () -> {
    checkEq(Card.parse("QH"), new Card(Rank.QUEEN, Suit.HEARTS));
    checkEq(new Card(Rank.TEN, Suit.SPADES).toString(), "TS");
    checkEq(Card.parse("2C").toString(), "2C");
    for (String bad : new String[] {"1H", "QX", "Q", "10H", "qh"}) {
        checkThrows(IllegalArgumentException.class, () -> Card.parse(bad));
    }
});

test("the deck", () -> {
    Deck deck = new Deck();
    checkEq(deck.size(), 52);
    checkEq(deck.deal().toString(), "2C");
    checkEq(deck.deal().toString(), "3C");
    Set<Card> seen = new HashSet<>();
    Deck shuffled = new Deck();
    shuffled.shuffle(new Random(7));
    while (shuffled.size() > 0) seen.add(shuffled.deal());
    checkEq(seen.size(), 52);
    checkThrows(IllegalStateException.class, shuffled::deal);
});

test("every category", () -> {
    checkEq(cat.apply("AS KD 7H 4C 2S"), Category.HIGH_CARD);
    checkEq(cat.apply("7H 7C AS KD 2S"), Category.PAIR);
    checkEq(cat.apply("7H 7C KS KD 2S"), Category.TWO_PAIR);
    checkEq(cat.apply("7H 7C 7S KD 2S"), Category.THREE_OF_A_KIND);
    checkEq(cat.apply("5H 6C 7S 8D 9S"), Category.STRAIGHT);
    checkEq(cat.apply("AH 2C 3S 4D 5S"), Category.STRAIGHT);
    checkEq(cat.apply("TH JC QS KD AS"), Category.STRAIGHT);
    checkEq(cat.apply("2H 7H 9H JH KH"), Category.FLUSH);
    checkEq(cat.apply("KS KH 4D 4C KC"), Category.FULL_HOUSE);
    checkEq(cat.apply("9S 9H 9D 9C 2H"), Category.FOUR_OF_A_KIND);
    checkEq(cat.apply("AH 2H 3H 4H 5H"), Category.STRAIGHT_FLUSH);
    checkEq(cat.apply("QH KH AH 2H 3H"), Category.FLUSH);
});

test("tiebreak ranks", () -> {
    checkEq(Poker.evaluate(Poker.parseHand("7H 7C AS KD 2S")).tiebreak(), List.of(Rank.SEVEN, Rank.ACE, Rank.KING, Rank.TWO));
    checkEq(Poker.evaluate(Poker.parseHand("KS KH 4D 4C KC")).tiebreak(), List.of(Rank.KING, Rank.FOUR));
    checkEq(Poker.evaluate(Poker.parseHand("AH 2C 3S 4D 5S")).tiebreak(), List.of(Rank.FIVE));
});

test("comparing hands", () -> {
    checkEq(Poker.compare("7H 7C AS KD 2S", "AH QC 9S 5D 3S"), 1);
    checkEq(Poker.compare("7H 7C AS KD 2S", "7D 7S AC QD 3S"), 1);
    checkEq(Poker.compare("AH 2C 3S 4D 5S", "2H 3C 4S 5D 6S"), -1);
    checkEq(Poker.compare("2H 7H 9H JH KH", "2S 7S 9S JS KS"), 0);
    checkEq(Poker.compare("9S 9H 9D 9C 2H", "KS KH 4D 4C KC"), 1);
    checkEq(Poker.compare("4S 4H 8D 8C AH", "4D 4C 8S 8H KH"), 1);
});

test("bad hands", () -> {
    checkThrows(IllegalArgumentException.class, () -> Poker.evaluate(Poker.parseHand("AS KD 7H 4C")));
    checkThrows(IllegalArgumentException.class, () -> Poker.evaluate(Poker.parseHand("AS AS 7H 4C 2D")));
});

